import{_ as i,C as o,o as a,c as l,a2 as r,E as n}from"./chunks/framework.BUrnCmah.js";const b=JSON.parse('{"title":"Progetto Domotico - Il Sistema Ibrido","description":"Come progettare una smart home affidabile, modulare e incentrata sul controllo locale con Home Assistant.","frontmatter":{"title":"Progetto Domotico - Il Sistema Ibrido","description":"Come progettare una smart home affidabile, modulare e incentrata sul controllo locale con Home Assistant."},"headers":[],"relativePath":"blogs/overview/hybrid-system.md","filePath":"blogs/overview/hybrid-system.md"}'),s={name:"blogs/overview/hybrid-system.md"};function d(c,e,g,u,m,h){const t=o("RelatedGuides");return a(),l("div",null,[e[0]||(e[0]=r('<h1 id="💡-progetto-domotico-strategico-il-sistema-ibrido" tabindex="-1">💡 Progetto Domotico Strategico: Il Sistema Ibrido <a class="header-anchor" href="#💡-progetto-domotico-strategico-il-sistema-ibrido" aria-label="Permalink to &quot;💡 Progetto Domotico Strategico: Il Sistema Ibrido&quot;">​</a></h1><p>L&#39;obiettivo è costruire un ecosistema <strong>potente, economico e rispettoso della privacy</strong>, utilizzando <strong>Home Assistant (HA)</strong> come cuore pulsante. L&#39;approccio ibrido permette di sfruttare il meglio di ogni tecnologia (Zigbee, Thread, Wi-Fi locale e servizi cloud mirati) senza restare prigionieri di un singolo marchio.</p><h2 id="🧠-home-assistant-il-cervello-locale-e-aperto" tabindex="-1">🧠 Home Assistant: Il Cervello Locale e Aperto <a class="header-anchor" href="#🧠-home-assistant-il-cervello-locale-e-aperto" aria-label="Permalink to &quot;🧠 Home Assistant: Il Cervello Locale e Aperto&quot;">​</a></h2><p>Home Assistant è il software open-source che funge da <strong>Hub Centrale</strong>. A differenza dei kit commerciali chiusi, non dipende dai server di una singola azienda e mette in comunicazione dispositivi eterogenei sotto un&#39;unica logica.</p><h3 id="perche-scegliere-home-assistant" tabindex="-1">Perché scegliere Home Assistant? <a class="header-anchor" href="#perche-scegliere-home-assistant" aria-label="Permalink to &quot;Perché scegliere Home Assistant?&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Vantaggio Chiave</th><th style="text-align:left;">Descrizione Dettagliata</th><th style="text-align:left;">Impatto nel Sistema</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Privacy &amp; Controllo</strong></td><td style="text-align:left;">I dati restano all&#39;interno della rete domestica, senza abbonamenti obbligatori.</td><td style="text-align:left;">🔒 Massima Sicurezza</td></tr><tr><td style="text-align:left;"><strong>Multilinguaggio</strong></td><td style="text-align:left;">Gestisce simultaneamente Wi-Fi, Zigbee, Z-Wave, Bluetooth, Thread e Matter.</td><td style="text-align:left;">🌐 Interoperabilità</td></tr><tr><td style="text-align:left;"><strong>Automazioni Evolute</strong></td><td style="text-align:left;">Logiche granulari tra marche diverse (es. sensore Aqara che comanda una luce Philips Hue).</td><td style="text-align:left;">⚡ Flessibilità Totale</td></tr><tr><td style="text-align:left;"><strong>Hardware Flessibile</strong></td><td style="text-align:left;">Funziona su Mini PC, Raspberry Pi, server domestici o macchine virtuali.</td><td style="text-align:left;">💰 Costo Iniziale Contenuto</td></tr><tr><td style="text-align:left;"><strong>Dashboard Custom</strong></td><td style="text-align:left;">Interfacce touch su misura per smartphone, tablet a muro e desktop.</td><td style="text-align:left;">📱 Esperienza Utente</td></tr></tbody></table><h2 id="🛠️-l-architettura-del-sistema-ibrido" tabindex="-1">🛠️ L&#39;Architettura del Sistema Ibrido <a class="header-anchor" href="#🛠️-l-architettura-del-sistema-ibrido" aria-label="Permalink to &quot;🛠️ L&#39;Architettura del Sistema Ibrido&quot;">​</a></h2><p>Un sistema ibrido organizza i dispositivi su tre livelli in base a latenza, consumo e criticità.</p><h3 id="_1-livello-radio-locale-puro-📡" tabindex="-1">1. Livello Radio (Locale Puro) 📡 <a class="header-anchor" href="#_1-livello-radio-locale-puro-📡" aria-label="Permalink to &quot;1. Livello Radio (Locale Puro) 📡&quot;">​</a></h3><ul><li><strong>Zigbee / Thread (Spina Dorsale):</strong> ideale per sensori, pulsanti e illuminazione, collegati a Home Assistant tramite un <strong>Dongle USB</strong> dedicato (es. Home Assistant Connect ZBT-1 o Sonoff ZBDongle). <ul><li><em>Vantaggio:</em> nessuna dipendenza da internet e zero congestione sulla rete Wi-Fi.</li></ul></li><li><strong>Z-Wave (Opzionale):</strong> indicato per dispositivi critici (valvole idriche, serrature, allarmi) grazie alla banda sub-GHz dedicata a 868 MHz.</li></ul><h3 id="_2-livello-wi-fi-controllo-in-lan-🔌" tabindex="-1">2. Livello Wi-Fi (Controllo in LAN) 🔌 <a class="header-anchor" href="#_2-livello-wi-fi-controllo-in-lan-🔌" aria-label="Permalink to &quot;2. Livello Wi-Fi (Controllo in LAN) 🔌&quot;">​</a></h3><ul><li><strong>Dispositivi Shelly / ESPHome / Tasmota / Tuya Local:</strong> prodotti Wi-Fi che Home Assistant controlla direttamente sulla rete locale tramite <strong>API locali</strong>, evitando il passaggio sui server del produttore. <ul><li><em>Vantaggio:</em> reattività immediata e funzionamento garantito anche senza connessione internet.</li></ul></li></ul><h3 id="_3-livello-cloud-solo-dove-aggiunge-valore-☁️" tabindex="-1">3. Livello Cloud (Solo Dove Aggiunge Valore) ☁️ <a class="header-anchor" href="#_3-livello-cloud-solo-dove-aggiunge-valore-☁️" aria-label="Permalink to &quot;3. Livello Cloud (Solo Dove Aggiunge Valore) ☁️&quot;">​</a></h3><p>In un impianto ibrido pragmatico, il cloud viene confinato alle sole funzioni in cui offre un reale valore aggiunto:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Funzionalità Cloud</th><th style="text-align:left;">Esempio Pratico</th><th style="text-align:left;">Ruolo nel Sistema</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Mappe Avanzate</strong></td><td style="text-align:left;">Robot aspirapolvere (Roborock, Dreame).</td><td style="text-align:left;">HA avvia o pianifica la pulizia, l&#39;app del brand gestisce la mappa.</td></tr><tr><td style="text-align:left;"><strong>Scene Dinamiche</strong></td><td style="text-align:left;">Effetti sincronizzati Philips Hue o Nanoleaf.</td><td style="text-align:left;">HA attiva la scena, il sistema gestisce le animazioni complesse.</td></tr><tr><td style="text-align:left;"><strong>Assistenti Vocali</strong></td><td style="text-align:left;">Integrazione con Google Assistant o Alexa.</td><td style="text-align:left;">HA espone le entità scelte, il cloud gestisce il riconoscimento.</td></tr><tr><td style="text-align:left;"><strong>Accesso Remoto</strong></td><td style="text-align:left;">Notifiche push e controllo fuori casa (Nabu Casa).</td><td style="text-align:left;">Tunnel cifrato sicuro senza esporre porte del router.</td></tr></tbody></table><h2 id="📋-configurazione-consigliata-per-iniziare" tabindex="-1">📋 Configurazione Consigliata per Iniziare <a class="header-anchor" href="#📋-configurazione-consigliata-per-iniziare" aria-label="Permalink to &quot;📋 Configurazione Consigliata per Iniziare&quot;">​</a></h2><h3 id="⚙️-hardware-centrale" tabindex="-1">⚙️ Hardware Centrale <a class="header-anchor" href="#⚙️-hardware-centrale" aria-label="Permalink to &quot;⚙️ Hardware Centrale&quot;">​</a></h3><ul><li><strong>Server:</strong> Mini PC (es. Intel N100) o Raspberry Pi 5 con SSD.</li><li><strong>Radio:</strong> Coordinator USB Zigbee/Thread affidabile collegato con prolunga USB lontano da porte USB 3.0 per ridurre le interferenze.</li></ul><h3 id="🛒-scelta-dei-dispositivi" tabindex="-1">🛒 Scelta dei Dispositivi <a class="header-anchor" href="#🛒-scelta-dei-dispositivi" aria-label="Permalink to &quot;🛒 Scelta dei Dispositivi&quot;">​</a></h3><ol><li><strong>Sensori (Zigbee):</strong> Aqara (clima, movimento, contatti porta) o IKEA Vallhorn.</li><li><strong>Illuminazione:</strong> Philips Hue (massima resa cromatica) o IKEA Tradfri (ottimo rapporto qualità-prezzo).</li><li><strong>Attuatori di Potenza (Wi-Fi LAN):</strong> moduli Shelly per tapparelle, punti luce e monitoraggio consumi.</li><li><strong>Clima:</strong> valvole termostatiche Zigbee o controller locali per climatizzatori.</li></ol><div class="tip custom-block"><p class="custom-block-title">Regola d&#39;oro del Sistema Ibrido</p><p>Preferisci sempre il <strong>controllo locale</strong> (Zigbee, Z-Wave, Matter o Wi-Fi con API LAN) per tutto ciò che riguarda luci, sensori e prese; usa il <strong>cloud</strong> solo come integrazione accessoria.</p></div><h2 id="🔗-prosegui-con-le-guide" tabindex="-1">🔗 Prosegui con le Guide <a class="header-anchor" href="#🔗-prosegui-con-le-guide" aria-label="Permalink to &quot;🔗 Prosegui con le Guide&quot;">​</a></h2>',22)),n(t,{items:[{icon:"🏡",tag:"Protocolli",title:"Guida ai Protocolli Domotici",description:"Confronto dettagliato tra Wi-Fi, Z-Wave, Zigbee 3.0, Thread e Matter.",link:"/blogs/overview/protocols-comparison"},{icon:"🛍️",tag:"Hardware",title:"Marche Consigliate e Integrazioni Locali",description:"Riepilogo e link alle analisi dedicate a Tuya / Smart Life e Bticino.",link:"/blogs/overview/recommended-brands"}]})])}const f=i(s,[["render",d]]);export{b as __pageData,f as default};
